{
  "findings": [
    {
      "check_id": "CKV_AWS_84",
      "title": "Elasticsearch domain logging is not enabled",
      "resource": "aws_elasticsearch_domain.log_search_database",
      "severity": "MEDIUM",
      "explanation": "The domain has no log publishing configuration, preventing application and slow logs from being sent to CloudWatch for operational and security monitoring."
    },
    {
      "check_id": "CKV_AWS_317",
      "title": "Elasticsearch audit logging is not enabled",
      "resource": "aws_elasticsearch_domain.log_search_database",
      "severity": "MEDIUM",
      "explanation": "Audit logs are not published, limiting visibility into authentication, authorization, and data access activity on this domain."
    },
    {
      "check_id": "CKV_AWS_228",
      "title": "Elasticsearch domain does not enforce an up-to-date TLS policy",
      "resource": "aws_elasticsearch_domain.log_search_database",
      "severity": "MEDIUM",
      "explanation": "No endpoint TLS policy is configured, so the domain may permit outdated TLS versions instead of enforcing TLS 1.2."
    },
    {
      "check_id": "CKV2_AWS_59",
      "title": "Elasticsearch dedicated master nodes are disabled",
      "resource": "aws_elasticsearch_domain.log_search_database",
      "severity": "MEDIUM",
      "explanation": "The cluster does not configure dedicated master nodes, increasing the risk that data-node resource pressure could affect cluster management and availability."
    }
  ],
  "patched_code": "variable "elasticsearch_master_user_arn" {
  description = "IAM user or role ARN used as the Elasticsearch fine-grained access control master user"
  type        = string
}

resource "aws_cloudwatch_log_group" "elasticsearch_logs" {
  name              = "/aws/elasticsearch/enterprise-log-analytics-es"
  retention_in_days = 365
}

resource "aws_cloudwatch_log_resource_policy" "elasticsearch_logs" {
  policy_name = "enterprise-log-analytics-es-logs"

  policy_document = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "es.amazonaws.com"
        }
        Action = [
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "logs:PutLogEventsBatch"
        ]
        Resource = "${aws_cloudwatch_log_group.elasticsearch_logs.arn}:*"
      }
    ]
  })
}

resource "aws_elasticsearch_domain" "log_search_database" {
  domain_name           = "enterprise-log-analytics-es"
  elasticsearch_version = "7.10"

  cluster_config {
    instance_type           = var.elasticsearch_instance_type
    instance_count          = 2
    dedicated_master_enabled = true
    dedicated_master_type    = var.elasticsearch_instance_type
    dedicated_master_count   = 3
  }

  vpc_options {
    subnet_ids         = [aws_subnet.data_subnet_az1.id]
    security_group_ids = [aws_security_group.elasticsearch_sg.id]
  }

  ebs_options {
    ebs_enabled = true
    volume_size = 20
    volume_type = "gp2"
  }

  encrypt_at_rest {
    enabled = true
  }

  node_to_node_encryption {
    enabled = true
  }

  domain_endpoint_options {
    enforce_https       = true
    tls_security_policy = "Policy-Min-TLS-1-2-2019-07"
  }

  advanced_security_options {
    enabled                        = true
    internal_user_database_enabled = false

    master_user_options {
      master_user_arn = var.elasticsearch_master_user_arn
    }
  }

  log_publishing_options {
    cloudwatch_log_group_arn = aws_cloudwatch_log_group.elasticsearch_logs.arn
    log_type                 = "ES_APPLICATION_LOGS"
    enabled                  = true
  }

  log_publishing_options {
    cloudwatch_log_group_arn = aws_cloudwatch_log_group.elasticsearch_logs.arn
    log_type                 = "SEARCH_SLOW_LOGS"
    enabled                  = true
  }

  log_publishing_options {
    cloudwatch_log_group_arn = aws_cloudwatch_log_group.elasticsearch_logs.arn
    log_type                 = "INDEX_SLOW_LOGS"
    enabled                  = true
  }

  log_publishing_options {
    cloudwatch_log_group_arn = aws_cloudwatch_log_group.elasticsearch_logs.arn
    log_type                 = "AUDIT_LOGS"
    enabled                  = true
  }

  depends_on = [aws_cloudwatch_log_resource_policy.elasticsearch_logs]
}
",
  "fix_summary": "Enabled CloudWatch application, slow, and audit logging; enforced HTTPS with TLS 1.2; and configured three dedicated master nodes. Fine-grained access control, node-to-node encryption, and encryption at rest were enabled as prerequisites for secure audit logging."
}
